@T.prim_func
def matmul_kernel(
    A: T.Buffer((M, K), Float16),
    B: T.Buffer((K, N), Float16),
    C: T.Buffer((M, N), Float16)
):
    # Shared memory for tiles
    shared_A = T.alloc_shared((T.ceildiv(K, 32), 32), Float16)
    shared_B = T.alloc_shared((32, T.ceildiv(N, 32)), Float16)

