    tx = T.thread_binding(0, 32, "threadIdx.x")
    ty = T.thread_binding(0, 32, "threadIdx.y")

    # Block indices
    bx = T.thread_binding(0, grid_x, "blockIdx.x")
    by = T.thread_binding(0, grid_y, "blockIdx.y")

    # Initialize accumulator
    acc = T.alloc_buffer((32, 32), Float16)

    # Loop over tiles
    for k in range(T.ceildiv(K, 32)):
        # Load tile of A into shared memory
        for i in range(32):
            for j in range(32):
                if (bx * 32 + i < M) and (k * 32 + j < K):
                    shared_A[i, j] = A[bx * 32 + i, k * 32 + j]
                else:
